import { useEffect, useState, type FormEvent } from 'react'
import { Link, useSearchParams, useNavigate } from 'react-router-dom'
import { apiClient, type ResetPasswordResponse } from '../../services/apiClient'
import logoUrl from '../../assets/logo.png'

export function ResetPasswordPage() {
  const [searchParams] = useSearchParams()
  const [email, setEmail] = useState(searchParams.get('email') ?? '')
  const [token, setToken] = useState(searchParams.get('token') ?? '')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    try {
      return (globalThis.localStorage?.getItem('fv-theme') as 'light' | 'dark') || 'light'
    } catch {
      return 'light'
    }
  })
  const navigate = useNavigate()

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme)
  }, [theme])

  const setAppTheme = (nextTheme: 'light' | 'dark') => {
    setTheme(nextTheme)
    document.documentElement.setAttribute('data-theme', nextTheme)
    try {
      globalThis.localStorage?.setItem('fv-theme', nextTheme)
    } catch {
      // ignore
    }
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault()
    setError('')
    setMessage('')

    if (newPassword !== confirmPassword) {
      setError('Passwords do not match.')
      return
    }

    if (newPassword.length < 8) {
      setError('Password must be at least 8 characters long.')
      return
    }

    setLoading(true)

    try {
      const response = await apiClient.post<ResetPasswordResponse>('/auth/reset-password', {
        email,
        token,
        newPassword,
      })
      setMessage(response.data.message)
      setTimeout(() => {
        navigate('/login')
      }, 2000)
    } catch {
      setError('Invalid or expired password reset token. Please request a new one.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <main className="login-page">
      {/* Top right theme toggle */}
      <div className="login-topbar">
        <div className="theme-toggle-group" role="group" aria-label="Theme mode switcher">
          <button
            type="button"
            className={`theme-toggle-btn ${theme === 'light' ? 'active' : ''}`}
            onClick={() => setAppTheme('light')}
          >
            <span aria-hidden="true">☀️</span> Light
          </button>
          <button
            type="button"
            className={`theme-toggle-btn ${theme === 'dark' ? 'active' : ''}`}
            onClick={() => setAppTheme('dark')}
          >
            <span aria-hidden="true">🌙</span> Dark
          </button>
        </div>
      </div>

      <div className="login-stage">
        {/* Left floating badge */}
        <aside className="login-wing login-wing--left" aria-hidden="true">
          <div className="live-floating-card live-floating-card--1">
            <span className="live-icon-badge">🔒</span>
            <div>
              <strong>Secure Password</strong>
              <small><span className="pulse-dot" /> Min 8 characters</small>
            </div>
          </div>
          <div className="live-floating-card live-floating-card--2">
            <span className="live-icon-badge">🛡️</span>
            <div>
              <strong>Tamper Evident</strong>
              <small>Audited updates</small>
            </div>
          </div>
        </aside>

        {/* Center Card */}
        <div className="simple-login-card">
          <div className="simple-login-brand">
            <img src={logoUrl} alt="Family Veda" width={56} height={56} />
            <h1>Family Veda</h1>
            <p>Clinical Decision Support</p>
          </div>

          <p className="eyebrow">Account security</p>
          <h2>Reset password</h2>
          <p className="muted">Enter your email, reset token, and your new password.</p>

          {error && <p className="form-error" role="alert">{error}</p>}
          {message && (
            <div style={{ padding: '10px 14px', borderRadius: '8px', background: 'rgba(16, 185, 129, 0.15)', border: '1px solid var(--primary)', marginBottom: '16px', fontSize: '0.9rem' }}>
              <span role="status">{message}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} noValidate>
            <label className="field">
              <span>Email address</span>
              <input
                type="email"
                required
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="name@example.invalid"
              />
            </label>

            <label className="field">
              <span>Reset token</span>
              <input
                type="text"
                required
                value={token}
                onChange={(e) => setToken(e.target.value)}
                placeholder="e.g. 8-character token"
                style={{ fontFamily: 'monospace', letterSpacing: '1px' }}
              />
            </label>

            <label className="field">
              <span>New password (min 8 characters)</span>
              <input
                type="password"
                required
                minLength={8}
                autoComplete="new-password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="••••••••"
              />
            </label>

            <label className="field">
              <span>Confirm new password</span>
              <input
                type="password"
                required
                minLength={8}
                autoComplete="new-password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="••••••••"
              />
            </label>

            <button type="submit" disabled={loading} className="button button--primary button--full" style={{ marginTop: '8px' }}>
              {loading ? 'Resetting Password…' : 'Set New Password'}
            </button>
          </form>

          <p className="privacy-note" style={{ marginTop: '20px' }}>
            <Link to="/login">Back to Sign In</Link> · <Link to="/forgot-password">Request new token</Link>
          </p>
        </div>

        {/* Right floating badge */}
        <aside className="login-wing login-wing--right" aria-hidden="true">
          <div className="live-floating-card live-floating-card--4">
            <span className="live-icon-badge">🔑</span>
            <div>
              <strong>PBKDF2 Hashing</strong>
              <small>Industry standard</small>
            </div>
          </div>
          <div className="live-floating-card live-floating-card--5">
            <span className="live-icon-badge">⚡</span>
            <div>
              <strong>Single-Use Token</strong>
              <small>Instant expiration</small>
            </div>
          </div>
        </aside>
      </div>
    </main>
  )
}
